export function ChessGame({ onReact, difficulty = 'standard' }) { const [board, setBoard] = useState(chessStart); const [selected, setSelected] = useState(null); const [turn, setTurn] = useState('w'); const [winner, setWinner] = useState(null); const move = (to) => { if (winner || turn !== 'w') return; const legal = selected !== null && chessMoves(board, selected).includes(to); if (!legal) { setSelected(board[to]?.[0] === 'w' ? to : null); return } const next = [...board]; const moving = next[selected]; next[to] = moving[1] === 'p' && Math.floor(to / 8) === 0 ? 'wq' : moving; next[selected] = null; if (next[to] === 'bk') { setWinner('you'); onReact('win') } else { setTurn('b'); setSelected(null) } setBoard(next) }
  useEffect(() => { if (turn !== 'b' || winner) return undefined; const timer = window.setTimeout(() => { const moves = chessLegalMoves(board, 'b'); if (!moves.length) { setWinner('you'); onReact('win'); return } const captures = moves.filter(({ to }) => board[to]?.[0] === 'w'); const pool = difficulty === 'hard' && captures.length ? captures : moves; const choice = pool[Math.floor(Math.random() * pool.length)]; const next = [...board]; const moving = next[choice.from]; next[choice.to] = moving[1] === 'p' && Math.floor(choice.to / 8) === 7 ? 'bq' : moving; next[choice.from] = null; if (next[choice.to] === 'wk') { setWinner('owl'); onReact('draw') } setBoard(next); setTurn('w') }, difficulty === 'hard' ? 320 : difficulty === 'easy' ? 800 : 560); return () => window.clearTimeout(timer) }, [board, difficulty, onReact, turn, winner])
  const reset = () => { setBoard(chessStart()); setSelected(null); setTurn('w'); setWinner(null) }; const legalTargets = selected === null ? [] : chessMoves(board, selected)
  return <div className="dk-game-panel dk-modern-game-panel dk-chess-panel dk-chess-full-panel"><div className="dk-game-toolbar"><span className="dk-live-status"><i />{winner ? `${winner === 'you' ? 'You' : 'Owl'} win` : turn === 'w' ? 'Your turn' : 'Owl is thinking'}</span><span className="dk-score-chip">{DIFFICULTIES[difficulty].label} chess</span></div><div className="dk-chess-workspace"><div className="dk-chess-board-wrap"><div className="dk-chess-ranks" aria-hidden="true">{[8,7,6,5,4,3,2,1].map((rank) => <span key={rank}>{rank}</span>)}</div><div><div className="dk-chess-board" role="grid" aria-label="Owl Chess board">{board.map((piece, index) => <button type="button" key={index} className={`dk-chess-square ${(Math.floor(index / 8) + index) % 2 ? 'is-dark' : 'is-light'} ${selected === index ? 'is-selected' : ''} ${legalTargets.includes(index) ? 'is-target' : ''}`} onClick={() => move(index)} aria-label={`${String.fromCharCode(97 + index % 8)}${8 - Math.floor(index / 8)}${piece ? ` ${piece}` : ''}`}><span>{piece ? CHESS_SYMBOLS[piece] : legalTargets.includes(index) ? '·' : ''}</span>{index >= 56 && <small className="dk-chess-file" aria-hidden="true">{String.fromCharCode(97 + index % 8)}</small>}</button>)}</div></div></div><aside className="dk-chess-side-panel"><span className="dk-kicker">Owl Chess</span><h3>{winner ? 'Round complete' : turn === 'w' ? 'Your move' : 'Owl is thinking'}</h3><p>{winner ? 'Reset the board when you are ready for another thoughtful round.' : 'Choose a white piece, then choose a highlighted square. The full board stays in view while you play.'}</p><div className="dk-chess-legend"><span><i className="is-you" />Your pieces</span><span><i className="is-owl" />Owl pieces</span></div><button type="button" className="dk-secondary-button" onClick={reset}>Restart board</button></aside></div><div className="dk-game-footer"><p aria-live="polite">{winner ? 'A thoughtful round. Ready to reset the board?' : 'Tap a white piece, then tap a highlighted square.'}</p></div></div> }



const SNAKES_LADDERS = { 4: 14, 9: 31, 17: 7, 20: 38, 28: 84, 40: 59, 51: 67, 54: 34, 62: 19, 63: 81, 64: 60, 87: 24, 93: 73, 95: 75, 99: 78 }
const AVATAR_OPTIONS = [{ id: 'scout', label: 'Scout', mark: '✦' }, { id: 'spark', label: 'Spark', mark: '✺' }, { id: 'leaf', label: 'Leaf', mark: '❧' }, { id: 'moon', label: 'Moon', mark: '☾' }]
const THEME_OPTIONS = [{ id: 'canopy', label: 'Canopy', swatch: '#2c7771' }, { id: 'moonlit', label: 'Moonlit', swatch: '#425b9e' }, { id: 'sunset', label: 'Sunset', swatch: '#b76558' }, { id: 'honey', label: 'Honey nest', swatch: '#a37d36' }]
const DIE_PIP_POSITIONS = { 1: ['center'], 2: ['top-left', 'bottom-right'], 3: ['top-left', 'center', 'bottom-right'], 4: ['top-left', 'top-right', 'bottom-left', 'bottom-right'], 5: ['top-left', 'top-right', 'center', 'bottom-left', 'bottom-right'], 6: ['top-left', 'top-right', 'middle-left', 'middle-right', 'bottom-left', 'bottom-right'] }
function moveBoardToken(position, die) { const next = position + die; return next > 100 ? position : SNAKES_LADDERS[next] || next }
function chooseOwlRoll(position, difficulty) { const max = difficulty === 'easy' ? 5 : 6; const options = Array.from({ length: max }, (_, index) => index + 1); if (difficulty === 'master') { const winning = options.find((value) => position + value >= 100); if (winning) return winning; const ladder = options.find((value) => SNAKES_LADDERS[position + value] > position + value); if (ladder) return ladder } if (difficulty === 'expert') { const safe = options.filter((value) => !SNAKES_LADDERS[position + value] || SNAKES_LADDERS[position + value] >= position + value); return safe[Math.floor(Math.random() * safe.length)] || options[Math.floor(Math.random() * options.length)] } return options[Math.floor(Math.random() * options.length)] }
function numberAtCell(index) { const row = Math.floor(index / 10); const col = index % 10; const rowFromBottom = 9 - row; return rowFromBottom % 2 === 0 ? rowFromBottom * 10 + col + 1 : rowFromBottom * 10 + (10 - col) }
function boardPoint(number) { const zeroBased = Math.max(0, number - 1); const rowFromBottom = Math.floor(zeroBased / 10); const offset = zeroBased % 10; const col = rowFromBottom % 2 === 0 ? offset : 9 - offset; return { x: col * 10 + 5, y: (9 - rowFromBottom) * 10 + 5 } }
function snakePath(start, end) { const a = boardPoint(start); const b = boardPoint(end); const bend = (a.x + b.x) / 2 + (a.y < b.y ? 7 : -7); return `M ${a.x} ${a.y} C ${bend} ${a.y + 8}, ${bend} ${b.y - 8}, ${b.x} ${b.y}` }
function SnakeLadderArtwork() { return <svg className="dk-ladder-art" viewBox="0 0 100 100" aria-hidden="true">{Object.entries(SNAKES_LADDERS).map(([from, to]) => { const start = Number(from); const end = Number(to); const a = boardPoint(start); const b = boardPoint(end); if (end < start) return <g key={`${from}-${to}`} className="dk-snake-art"><path d={snakePath(start, end)} /><circle cx={a.x} cy={a.y} r="1.35" /><path className="dk-snake-head" d={`M ${a.x - 1.8} ${a.y - 1.2} Q ${a.x} ${a.y - 3.1} ${a.x + 1.8} ${a.y - 1.2}`} /></g>; const dx = b.x - a.x; const dy = b.y - a.y; const length = Math.sqrt(dx * dx + dy * dy); const ux = dx / length; const uy = dy / length; const px = -uy * 1.8; const py = ux * 1.8; const x1 = a.x + ux * 1.5; const y1 = a.y + uy * 1.5; const x2 = b.x - ux * 1.5; const y2 = b.y - uy * 1.5; return <g key={`${from}-${to}`} className="dk-ladder-art"><line x1={x1 + px} y1={y1 + py} x2={x2 + px} y2={y2 + py} /><line x1={x1 - px} y1={y1 - py} x2={x2 - px} y2={y2 - py} />{Array.from({ length: 6 }, (_, index) => { const t = (index + 1) / 7; const cx = x1 + (x2 - x1) * t; const cy = y1 + (y2 - y1) * t; return <line key={index} x1={cx + px} y1={cy + py} x2={cx - px} y2={cy - py} /> })}</g> })}</svg> }
function SnakeLadderDie({ value, rolling = false }) { const face = value || 1; return <div className={`dk-ladder-die ${rolling ? 'is-rolling' : ''} ${value ? '' : 'is-empty'}`} aria-label={value ? `Die showing ${value}` : 'Die ready to roll'}>{DIE_PIP_POSITIONS[face].map((position) => <i key={position} className={`is-${position}`} />)}</div> }

export function SnakeLadderGame({ onReact, difficulty = 'standard' }) {
  const [positions, setPositions] = useState({ you: 1, owl: 1 });
  const [avatar, setAvatar] = useState(() => window.localStorage.getItem('dk_ladder_avatar') || 'scout');
  const [theme, setTheme] = useState(() => window.localStorage.getItem('dk_ladder_theme') || 'canopy'); const [turn, setTurn] = useState('you'); const [die, setDie] = useState(null); const [rolling, setRolling] = useState(false); const [celebration, setCelebration] = useState(false); const [notice, setNotice] = useState('Climb the bright rungs, dodge the snakes, and reach 100.'); const winner = positions.you >= 100 ? 'you' : positions.owl >= 100 ? 'owl' : null
  const selectedAvatar = AVATAR_OPTIONS.find((option) => option.id === avatar) || AVATAR_OPTIONS[0]
  const chooseAvatar = (nextAvatar) => { setAvatar(nextAvatar); window.localStorage.setItem('dk_ladder_avatar', nextAvatar) }
  const chooseTheme = (nextTheme) => { setTheme(nextTheme); window.localStorage.setItem('dk_ladder_theme', nextTheme) }
  const reset = () => { setPositions({ you: 1, owl: 1 }); setTurn('you'); setDie(null); setRolling(false); setCelebration(false); setNotice('Climb the bright rungs, dodge the snakes, and reach 100.') }
  const finishTurn = useCallback((value) => { setRolling(false); if (winner) return; if (value === 6) { setTurn((current) => current); setNotice('A six! Roll again and keep climbing.') } else setTurn((current) => current === 'you' ? 'owl' : 'you'); setDie(null) }, [winner])
  const roll = () => { if (winner || turn !== 'you' || die || rolling) return; const value = Math.floor(Math.random() * 6) + 1; const landing = positions.you + value; const next = moveBoardToken(positions.you, value); const slide = SNAKES_LADDERS[landing]; setDie(value); setRolling(true); playPlaygroundSound(slide ? (slide > landing ? 'ladder' : 'snake') : 'roll'); setPositions((current) => ({ ...current, you: next })); setNotice(slide ? `${value} rolled. ${slide > landing ? 'A ladder lifts you' : 'A snake sends you back'} to ${slide}.` : `You rolled ${value}. You moved to ${next}.`); if (next >= 100) { window.setTimeout(() => { setRolling(false); setCelebration(true); playPlaygroundSound('victory'); onReact('win'); setNotice('You reached the nest. The Owl is impressed!') }, 520) } else window.setTimeout(() => finishTurn(value), 620) }
  useEffect(() => { if (winner || turn !== 'owl' || die || rolling) return undefined; const timer = window.setTimeout(() => { const value = chooseOwlRoll(positions.owl, difficulty); const next = moveBoardToken(positions.owl, value); setDie(value); setRolling(true); setPositions((current) => ({ ...current, owl: next })); setNotice(`The Owl rolled ${value} and reached ${next}.`); if (next >= 100) window.setTimeout(() => { setRolling(false); setNotice('The Owl reached 100 first. Ready for a rematch?'); onReact('draw') }, 620); else window.setTimeout(() => finishTurn(value), 760) }, difficulty === 'hard' ? 320 : 640); return () => window.clearTimeout(timer) }, [difficulty, die, finishTurn, onReact, positions.owl, rolling, turn, winner])
  return <div className={`dk-game-panel dk-modern-game-panel dk-ladder-panel dk-ladder-theme-${theme}`}>{celebration && <div className="dk-ladder-celebration" role="status" aria-live="assertive"><div className="dk-ladder-confetti" aria-hidden="true">{Array.from({ length: 18 }, (_, index) => <i key={index} style={{ '--confetti-index': index }} />)}</div><div className="dk-ladder-celebration-card"><span className="dk-ladder-celebration-owl" aria-hidden="true">🦉</span><span className="dk-kicker">Nest reached</span><h3>You outclimbed the Owl!</h3><p>The board is yours. Celebrate the win, then start a fresh climb whenever you’re ready.</p><button type="button" className="dk-online-primary" onClick={reset}>Climb again</button></div></div>}<div className="dk-game-toolbar"><span className="dk-live-status"><i />{winner ? `${winner === 'you' ? 'You' : 'Owl'} reached the nest` : turn === 'you' ? 'Your turn' : 'Owl is climbing'}</span><span className="dk-score-chip">{DIFFICULTIES[difficulty].label} climb</span></div><div className="dk-ladder-intro"><div><span className="dk-kicker">Owl’s climb</span><h3>Every move changes the story.</h3><p>Land on a ladder to rise. Land on a snake to slide. The first climber to reach 100 wins.</p></div><div className="dk-ladder-progress"><span>You</span><strong>{positions.you}</strong><small>of 100</small></div><div className="dk-ladder-progress is-owl"><span>Owl</span><strong>{positions.owl}</strong><small>of 100</small></div></div><div className="dk-ladder-customizer"><div><span className="dk-kicker">Your nest token</span><strong>{selectedAvatar.label}</strong><div className="dk-ladder-avatar-options">{AVATAR_OPTIONS.map((option) => <button type="button" key={option.id} className={`dk-ladder-avatar-option ${avatar === option.id ? 'is-active' : ''}`} onClick={() => chooseAvatar(option.id)} aria-label={`Choose ${option.label} avatar`} aria-pressed={avatar === option.id}><span>{option.mark}</span></button>)}</div></div><div><span className="dk-kicker">Board mood</span><strong>{THEME_OPTIONS.find((option) => option.id === theme)?.label || 'Canopy'}</strong><div className="dk-ladder-theme-options">{THEME_OPTIONS.map((option) => <button type="button" key={option.id} className={`dk-ladder-theme-option ${theme === option.id ? 'is-active' : ''}`} onClick={() => chooseTheme(option.id)} aria-label={`Choose ${option.label} board theme`} aria-pressed={theme === option.id}><i style={{ background: option.swatch }} />{option.label}</button>)}</div></div></div><div className="dk-ladder-board-shell"><div className="dk-ladder-board" aria-label="Traditional Snake and Ladder board">{Array.from({ length: 100 }, (_, index) => { const number = numberAtCell(index); const isLadder = Boolean(SNAKES_LADDERS[number] && SNAKES_LADDERS[number] > number); const isSnake = Boolean(SNAKES_LADDERS[number] && SNAKES_LADDERS[number] < number); const tokens = [positions.you === number ? 'you' : null, positions.owl === number ? 'owl' : null].filter(Boolean); return <div key={number} className={`dk-ladder-cell ${number % 2 ? 'is-odd' : 'is-even'} ${isLadder ? 'is-ladder' : ''} ${isSnake ? 'is-snake' : ''} ${number === 1 ? 'is-start' : ''} ${number === 100 ? 'is-finish' : ''}`}><span>{number}</span>{tokens.length > 0 && <div className="dk-ladder-piece-stack">{tokens.map((token) => <b key={token} className={`dk-ladder-token is-${token}`} aria-label={token === 'you' ? `${selectedAvatar.label} player token` : 'Owl token'}>{token === 'you' ? selectedAvatar.mark : 'O'}</b>)}</div>}</div> })}<SnakeLadderArtwork /></div><div className="dk-ladder-board-caption"><span><i className="is-ladder" />Ladders lift you</span><span><i className="is-snake" />Snakes slide you back</span><span><i className="is-finish" />Reach the nest</span></div></div><div className="dk-ladder-control"><div className="dk-ladder-die-stage"><SnakeLadderDie value={die} rolling={rolling} /><span>{rolling ? 'Rolling…' : die ? `Rolled ${die}` : 'Ready'}</span></div><div className="dk-ladder-notice"><strong>{notice}</strong><p>{winner ? 'Ready to start a new climb?' : turn === 'you' ? 'Your turn — choose your luck.' : 'The Owl is deciding its next move.'}</p></div><div className="dk-ladder-actions"><button type="button" className="dk-online-primary dk-roll-button" onClick={roll} disabled={winner || turn !== 'you' || Boolean(die) || rolling}>{rolling ? 'Rolling…' : 'Roll the die'}</button><button type="button" className="dk-secondary-button" onClick={reset}>Restart</button></div></div><div className="dk-ladder-legend"><span><i className="is-you" />You · {positions.you}</span><span><i className="is-owl" />Owl · {positions.owl}</span><span>Board path is server-ready for online play</span></div></div>
}

const WHOT_SHAPES = ['circle', 'triangle', 'cross', 'square', 'star']; const WHOT_VALUES = [1, 2, 3, 4, 5, 7, 8, 10, 11, 12, 14];
function makeWhotDeck() { return [...WHOT_SHAPES.flatMap((shape) => WHOT_VALUES.map((value) => ({ id: `${shape}-${value}`, shape, value }))), ...Array.from({ length: 5 }, (_, index) => ({ id: `whot-${index}`, shape: 'whot', value: 20 }))].sort(() => Math.random() - 0.5) }
function whotLegal(card, top) { return card.shape === 'whot' || card.shape === top.shape || card.value === top.value }
function dealWhot() { const deck = makeWhotDeck(); return { deck: deck.slice(14), you: deck.slice(0, 7), owl: deck.slice(7, 14), discard: deck[14] } }
function whotLabel(card) { return card.shape === 'whot' ? 'WHOT' : `${card.shape} ${card.value}` }

export function WhotGame({ onReact, difficulty = 'standard' }) {
  const [game, setGame] = useState(dealWhot); const [turn, setTurn] = useState('you'); const [notice, setNotice] = useState('Play a matching card or draw one.'); const [called, setCalled] = useState(false); const winner = game.you.length === 0 ? 'you' : game.owl.length === 0 ? 'owl' : null
  const reset = () => { setGame(dealWhot()); setTurn('you'); setNotice('Play a matching card or draw one.'); setCalled(false) }
  const draw = () => { if (winner || turn !== 'you' || !game.deck.length) return; const [card, ...rest] = game.deck; setGame((current) => ({ ...current, deck: rest, you: [...current.you, card] })); setNotice(`You drew ${whotLabel(card)}.`); setTurn('owl') }
  const play = (card) => { if (winner || turn !== 'you' || !whotLegal(card, game.discard)) return; const nextHand = game.you.filter((item) => item.id !== card.id); setGame((current) => ({ ...current, you: nextHand, discard: card })); setCalled(false); if (nextHand.length === 0) { onReact('win'); setNotice('You emptied your hand. Owl says: Whot!') } else { setNotice(nextHand.length === 1 ? 'One card left. Call Whot!' : `You played ${whotLabel(card)}.`); setTurn('owl') } }
  useEffect(() => { if (winner || turn !== 'owl') return undefined; const timer = window.setTimeout(() => { const legal = game.owl.filter((card) => whotLegal(card, game.discard)); const choice = (difficulty === 'hard' ? legal.find((card) => card.shape === 'whot') : null) || legal[0]; if (choice) { const nextHand = game.owl.filter((card) => card.id !== choice.id); setGame((current) => ({ ...current, owl: nextHand, discard: choice })); setNotice(`The Owl played ${whotLabel(choice)}.`); if (nextHand.length === 0) { onReact('draw'); setNotice('The Owl emptied its hand. Ready for another round?') } else setTurn('you') } else if (game.deck.length) { const [card, ...rest] = game.deck; setGame((current) => ({ ...current, deck: rest, owl: [...current.owl, card] })); setNotice('The Owl drew a card. Your turn.'); setTurn('you') } else { setTurn('you'); setNotice('The deck is empty. Keep playing the open hand.') } }, difficulty === 'hard' ? 360 : difficulty === 'easy' ? 780 : 560); return () => window.clearTimeout(timer) }, [difficulty, game.deck, game.discard, game.owl, onReact, turn, winner])
  const callWhot = () => { if (game.you.length === 1) { setCalled(true); setNotice('Whot called! Finish the round.'); } else setNotice('Call Whot when you have one card left.') }
  return <div className="dk-game-panel dk-modern-game-panel dk-whot-panel"><div className="dk-game-toolbar"><span className="dk-live-status"><i />{winner ? `${winner === 'you' ? 'You' : 'Owl'} win` : turn === 'you' ? 'Your turn' : 'Owl is thinking'}</span><span className="dk-score-chip">{DIFFICULTIES[difficulty].label} Whot</span></div><div className="dk-whot-table"><div className="dk-whot-opponent"><span className="dk-kicker">Owl hand</span><strong>{game.owl.length} cards</strong><div className="dk-whot-back-row">{game.owl.slice(0, Math.min(game.owl.length, 7)).map((card) => <span key={card.id}>✦</span>)}</div></div><div className="dk-whot-discard"><span className="dk-kicker">On the table</span><div className={`dk-whot-card is-${game.discard.shape}`}><strong>{game.discard.shape === 'whot' ? 'W' : game.discard.value}</strong><small>{game.discard.shape}</small></div><p>{notice}</p></div><div className="dk-whot-hand"><span className="dk-kicker">Your hand · {game.you.length}</span><div className="dk-whot-cards">{game.you.map((card) => <button type="button" key={card.id} className={`dk-whot-card is-${card.shape} ${whotLegal(card, game.discard) ? 'is-legal' : ''}`} onClick={() => play(card)} disabled={turn !== 'you' || !whotLegal(card, game.discard)}><strong>{card.shape === 'whot' ? 'W' : card.value}</strong><small>{card.shape}</small></button>)}</div></div></div><div className="dk-game-footer"><p aria-live="polite">{game.you.length === 1 && !called ? 'One card left? Call Whot before you finish.' : 'Match the shape or number. Whot cards can change the shape.'}</p><button type="button" className="dk-online-primary" onClick={draw} disabled={winner || turn !== 'you' || !game.deck.length}>Draw card</button><button type="button" className="dk-secondary-button" onClick={callWhot}>Call Whot</button><button type="button" className="dk-secondary-button" onClick={reset}>Restart hand</button></div></div>
}
